  "Interactive reports are limited to a configurable date range. Large historical requests should run as scheduled jobs and deliver a secure file link.": "التقارير التفاعلية محدودة بفترة قابلة للتهيئة. الطلبات التاريخية الكبيرة تُشغّل كمهام مجدولة وتوفر رابط ملف آمن.",
  "Invoice date:": "تاريخ الفاتورة:",
  "Invoice summary": "ملخص الفاتورة",
  "It is not a target. A level is supported by the work that was clinically necessary and actually done — raising an element to reach a code is the thing this panel is meant to make visible, not easier. Office and outpatient levels are selected by medical decision making": "ليس هدفاً. يدعم المستوى العمل الضروري سريرياً والمنفذ فعلاً. تُظهر هذه اللوحة رفع العناصر للوصول إلى رمز ولا تسهّله. تُحدد مستويات العيادات باتخاذ القرار الطبي",
  "Keyboard shortcuts are switched off in your preferences. The list below is what they would be.": "اختصارات لوحة المفاتيح معطلة في تفضيلاتك. أدناه قائمة بما ستكون عليه.",
