  "is resolved server-side at dispatch and is never sent to a browser, so it cannot be read, replayed or edited from here — changing one is a server deployment.": "يُحل على الخادم عند الإرسال ولا يُرسل للمتصفح؛ فلا يمكن قراءته أو إعادة استخدامه أو تعديله هنا. تغييره يتطلب نشر الخادم.",
  "is worth showing: 20 because someone chose 20 and 20 because nothing is configured look identical in the number alone.": "يستحق العرض: العدد 20 يبدو نفسه سواء اختاره شخص أو لم يُضبط شيء.",
