  "Proposes orders from this service's orderable catalogue for the documented problem. Selection only, never invention, and nothing is placed until you accept it.": "يقترح طلبات من دليل الخدمة للمشكلة الموثقة. اختيار فقط دون اختراع ولا يُنفّذ شيء حتى تقبله.",
