  "Adult context: age and sex rules apply only where clinically relevant.": "سياق البالغين: تُطبق قواعد العمر والجنس عند الصلة السريرية فقط.",
  "Paediatric context: guardian as source, weight-based safety, age-specific ranges and consent rules apply.": "سياق الأطفال: الوصي مصدر المعلومات والسلامة حسب الوزن ونطاقات العمر وقواعد الموافقة.",
  "Older adult context: falls, cognition, function, polypharmacy, caregiver context and goals of care are surfaced.": "سياق المسنين: تُعرض مخاطر السقوط والإدراك والوظيفة وتعدد الأدوية ومقدم الرعاية وأهدافها.",
  "Pregnancy context: gestational status, maternal and fetal warning signs, and medication and imaging safety are surfaced.": "سياق الحمل: تُعرض حالة الحمل وعلامات التحذير للأم والجنين وسلامة الدواء والتصوير.",
  "Complex multimorbidity: problem reconciliation, competing risks, medication burden and care-plan ownership are prioritised.": "الأمراض المتعددة المعقدة: الأولوية لمطابقة المشكلات والمخاطر المتنافسة وعبء الدواء ومسؤولية الخطة.",
  "Paediatrics with a non-paediatric patient context. Valid for adolescent and transition clinics; confirm the age ranges and permissions are right for this service.": "طب الأطفال مع سياق غير طفولي. صالح لعيادات المراهقين والانتقال؛ تحقق من العمر والصلاحيات المناسبة للخدمة.",
  "Paediatric context outside Paediatrics. The specialty must explicitly support paediatric practice, age ranges and consent handling.": "سياق أطفال خارج طب الأطفال. يجب أن يدعم التخصص صراحة ممارسة الأطفال ونطاقات العمر ومعالجة الموافقة.",
  "Pregnancy with Orthopaedics: medication and imaging safety considerations apply. This is a prompt, not a reason to withhold clinically indicated care.": "الحمل مع العظام: تنطبق سلامة الدواء والتصوير. هذا تذكير وليس سبباً لحجب الرعاية اللازمة سريرياً.",
  "Pregnancy with Psychiatry: perinatal mental-health pathways and medication-safety considerations apply.": "الحمل مع الطب النفسي: تنطبق مسارات الصحة النفسية حول الولادة واعتبارات سلامة الأدوية.",
  "Obstetrics & Gynaecology with a paediatric context may be adolescent gynaecology. Age, consent and privacy rules for the jurisdiction apply.": "التوليد والنساء بسياق طفولي قد يكون طب نساء المراهقات. تنطبق قواعد العمر والموافقة والخصوصية المحلية.",
  "Complex multimorbidity in Paediatrics usually implies a shared-care or long-term-conditions pathway rather than a single specialty plan.": "الأمراض المتعددة المعقدة لدى الأطفال تعني عادة مسار رعاية مشتركة أو طويلة الأمد بدلاً من خطة تخصص واحد.",
