  "designer.dependencyInvalid": "تحقق من تبعيات القوائم: اربط كل خيار تابع بقيمة أصل موجودة. يجب أن يكون الأصل قائمة؛ لا يُسمح بالحلقات أو السلاسل التي تتجاوز خمسة مستويات.",
